def transform(grid):
    h, w = len(grid), len(grid[0])
    out = []
    for band in range(3):
        for r in range(h):
            sr = h - 1 - r if band in (0, 2) else r
            row = []
            for side in range(2):
                for c in range(w):
                    sc = w - 1 - c if side == 0 else c
                    row.append(grid[sr][sc])
            out.append(row)
    return out
